function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Accent bar on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: 5.625,
    fill: { color: theme.accent }
  });

  // Decorative geometric block top-right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.5, y: 0, w: 2.5, h: 1.2,
    fill: { color: theme.secondary, transparency: 60 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.2, y: 1.2, w: 1.8, h: 0.6,
    fill: { color: theme.accent, transparency: 50 }
  });

  // Main title
  slide.addText("DeepSeek-V2", {
    x: 0.5, y: 1.4, w: 9, h: 1.2,
    fontSize: 60, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    margin: 0
  });

  // Subtitle
  slide.addText("Efficient MoE Language Model with Multi-Head Latent Attention", {
    x: 0.5, y: 2.6, w: 8, h: 0.7,
    fontSize: 22, fontFace: "Arial",
    color: theme.light,
    margin: 0
  });

  // Divider line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.45, w: 3, h: 0.04,
    fill: { color: theme.accent }
  });

  // Key stats row
  const stats = [
    { value: "236B", label: "Total Parameters" },
    { value: "21B", label: "Activated per Token" },
    { value: "128K", label: "Context Length" }
  ];
  const statStartX = 0.5;
  const statW = 2.5;
  stats.forEach((s, i) => {
    const sx = statStartX + i * statW;
