  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: theme.accent }
  });

  // Slide title
  slide.addText("The LLM Scaling Dilemma", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });

  slide.addText("Performance vs. Training Cost and Inference Speed", {
    x: 0.5, y: 0.85, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Arial",
    color: theme.secondary,
    margin: 0
  });

  // Three challenge cards
  const challenges = [
    {
      title: "KV Cache Bottleneck",
      body: "Standard MHA stores full K/V pairs per head per token. At 128K context, cache size becomes prohibitive for autoregressive generation.",
      icon: "MHA"
    },
    {
      title: "Training Cost Crisis",
      body: "Dense models require activating all parameters. A 70B dense model costs 3-5× more to train than a comparable MoE architecture.",
      icon: "Dense"
    },
    {
      title: "Efficiency Trade-offs",
      body: "GQA and MQA reduce cache at the cost of model quality — they are approximations, not solutions.",
      icon: "GQA"
    }
  ];

  const cardW = 2.85;
  const cardH = 2.6;
  const cardY = 1.55;
  const cardGap = 0.22;

  challenges.forEach((c, i) => {
    const cx = 0.5 + i * (cardW + cardGap);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", color: "000000", blur: 8, offset: 2, angle: 135, opacity: 0.08 }
    });

    // Accent top strip
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: 0.06,
      fill: { color: theme.accent }
    });

    // Icon badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx + 0.15, y: cardY + 0.2, w: 0.5, h: 0.5,
      fill: { color: theme.primary }
    });
    slide.addText(c.icon, {
      x: cx + 0.15, y: cardY + 0.2, w: 0.5, h: 0.5,
      fontSize: 9, fontFace: "Arial",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Card title
    slide.addText(c.title, {
      x: cx + 0.15, y: cardY + 0.8, w: cardW - 0.3, h: 0.45,
      fontSize: 14, fontFace: "Arial",
      color: theme.primary, bold: true,
      margin: 0
    });

    // Card body
    slide.addText(c.body, {
      x: cx + 0.15, y: cardY + 1.25, w: cardW - 0.3, h: 1.2,
      fontSize: 11, fontFace: "Arial",
      color: theme.secondary,
      margin: 0
    });
  });

  // Bottom insight bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.5, w: 9, h: 0.7,
    fill: { color: theme.primary }
  });
  slide.addText("Need: Architecture innovations that reduce costs without sacrificing performance", {
    x: 0.65, y: 4.5, w: 8.7, h: 0.7,
    fontSize: 14, fontFace: "Arial",
    color: "FFFFFF",
    valign: "middle",
    margin: 0
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

