// slide-07.js — MMLU Performance Comparison
const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 7, title: 'MMLU Performance Comparison' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: theme.accent }
  });

  slide.addText("MMLU Performance vs. Activated Parameters", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 30, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });

  slide.addText("DeepSeek-V2 achieves top-tier MMLU with far fewer activated parameters — Pareto-optimal efficiency", {
    x: 0.5, y: 0.85, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary,
    margin: 0
  });

  // Scatter plot using shapes
  // X-axis: Activated params (0 to 80B), Y-axis: MMLU score (60 to 82)
  const plotX = 0.6;
  const plotY = 1.35;
  const plotW = 5.8;
  const plotH = 3.4;

  // Plot background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: plotX, y: plotY, w: plotW, h: plotH,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 }
  });

  // Y-axis gridlines and labels (MMLU: 60, 65, 70, 75, 80)
  const mmluRange = { min: 60, max: 82 };
  const paramRange = { min: 0, max: 80 };

  for (let score = 60; score <= 80; score += 5) {
    const yFrac = (score - mmluRange.min) / (mmluRange.max - mmluRange.min);
    const yPos = plotY + plotH - (yFrac * plotH);

    // Gridline
    slide.addShape(pres.shapes.RECTANGLE, {
      x: plotX, y: yPos, w: plotW, h: 0.01,
      fill: { color: theme.light, transparency: 50 }
    });

    // Y-axis label
    slide.addText(String(score), {
      x: plotX - 0.4, y: yPos - 0.12, w: 0.35, h: 0.24,
      fontSize: 9, fontFace: "Arial",
      color: theme.secondary,
      align: "right", valign: "middle",
      margin: 0
    });
  }

  // X-axis labels (0, 20, 40, 60, 80B)
  for (let param = 0; param <= 80; param += 20) {
    const xFrac = (param - paramRange.min) / (paramRange.max - paramRange.min);
    const xPos = plotX + (xFrac * plotW);

    // X-axis label
    slide.addText(param + "B", {
      x: xPos - 0.25, y: plotY + plotH + 0.05, w: 0.5, h: 0.22,
      fontSize: 9, fontFace: "Arial",
      color: theme.secondary,
      align: "center",
      margin: 0
    });
  }

  // Axis labels
  slide.addText("Activated Parameters", {
    x: plotX, y: plotY + plotH + 0.3, w: plotW, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.secondary,
    align: "center",
    margin: 0
  });

  // Y-axis title (rotated via text, but simpler: vertical text box)
  slide.addText("MMLU Score", {
    x: plotX - 0.55, y: plotY + 0.8, w: 0.25, h: 1.8,
    fontSize: 10, fontFace: "Arial",
    color: theme.secondary,
    align: "center",
    margin: 0
  });

  // Data points: [activated, mmlu]
  const models = [
    { name: "DeepSeek-V2", params: 21, mmlu: 78.5, highlight: true },
    { name: "LLaMA 3 70B", params: 70, mmlu: 77.0, highlight: false },
    { name: "Mixtral 8×22B", params: 39, mmlu: 77.6, highlight: false },
    { name: "Qwen1.5 72B", params: 72, mmlu: 75.6, highlight: false },
    { name: "DeepSeek 67B", params: 67, mmlu: 73.0, highlight: false },
    { name: "LLaMA 2 70B", params: 70, mmlu: 69.0, highlight: false },
    { name: "Mixtral 8×7B", params: 13, mmlu: 70.6, highlight: false },
    { name: "LLaMA 3 8B", params: 8, mmlu: 65.0, highlight: false }
  ];

  const dotSize = 0.22;

  models.forEach((m) => {
    const xFrac = (m.params - paramRange.min) / (paramRange.max - paramRange.min);
    const yFrac = (m.mmlu - mmluRange.min) / (mmluRange.max - mmluRange.min);
    const cx = plotX + (xFrac * plotW);
    const cy = plotY + plotH - (yFrac * plotH);

    const dotColor = m.highlight ? theme.accent : theme.secondary;
    const dotFill = m.highlight ? theme.accent : theme.secondary;

    // Draw dot
    slide.addShape(pres.shapes.OVAL, {
      x: cx - dotSize / 2, y: cy - dotSize / 2, w: dotSize, h: dotSize,
      fill: { color: dotFill },
      line: m.highlight ? { color: theme.primary, width: 1.5 } : null
    });

    // Label for highlighted point
    if (m.highlight) {
      slide.addText("DeepSeek-V2", {
        x: cx - 0.55, y: cy - 0.38, w: 1.1, h: 0.25,
        fontSize: 9, fontFace: "Arial",
        color: theme.primary, bold: true,
        align: "center",
        margin: 0
      });
    }
  });

  // Reference image from source (figure_3.jpg)
  const refX = 6.55;
  const refY = 1.35;
  const refW = 3.15;
  const refH = 2.0;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: refX, y: refY, w: refW, h: refH,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 }
  });
  slide.addImage({
    path: "/app/benchmark/assets/figure_3.jpg",
    x: refX + 0.08, y: refY + 0.08, w: refW - 0.16, h: refH - 0.16
  });
  slide.addText("Source: arxiv.org/abs/2405.04434", {
    x: refX, y: refY + refH + 0.05, w: refW, h: 0.25,
    fontSize: 8, fontFace: "Arial",
    color: theme.secondary,
    align: "center",
    margin: 0
  });

  // Legend panel (right side, below image)
  const legendX = 6.55;
  const legendY = 3.55;
  const legendW = 3.15;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: legendX, y: legendY, w: legendW, h: 1.55,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 }
  });
  slide.addText("Key Comparison Data", {
    x: legendX + 0.12, y: legendY + 0.1, w: legendW - 0.24, h: 0.3,
    fontSize: 11, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });

  const legendItems = [
    { name: "DeepSeek-V2", params: "21B", score: "78.5", accent: true },
    { name: "LLaMA 3 70B", params: "70B", score: "77.0", accent: false },
    { name: "Mixtral 8×22B", params: "39B", score: "77.6", accent: false },
    { name: "Qwen1.5 72B", params: "72B", score: "75.6", accent: false }
  ];

  legendItems.forEach((item, i) => {
    const ly = legendY + 0.45 + i * 0.26;

    // Color dot
    slide.addShape(pres.shapes.OVAL, {
      x: legendX + 0.15, y: ly + 0.04, w: 0.14, h: 0.14,
      fill: { color: item.accent ? theme.accent : theme.secondary }
    });

    // Name
    slide.addText(item.name, {
      x: legendX + 0.35, y: ly, w: 1.5, h: 0.22,
      fontSize: 9, fontFace: "Arial",
      color: theme.primary, bold: item.accent,
      margin: 0
    });

    // Params
    slide.addText(item.params, {
      x: legendX + 1.75, y: ly, w: 0.6, h: 0.22,
      fontSize: 9, fontFace: "Arial",
      color: theme.secondary,
      align: "right",
      margin: 0
    });

    // Score
    slide.addText(item.score, {
      x: legendX + 2.4, y: ly, w: 0.55, h: 0.22,
      fontSize: 9, fontFace: "Arial",
      color: theme.accent, bold: true,
      align: "right",
      margin: 0
    });
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "03045e",
    secondary: "0077b6",
    accent: "00b4d8",
    light: "90e0ef",
    bg: "caf0f8"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

