    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });

  slide.addText("Fine-Grained Experts with Shared Expert Isolation — 42.5% Training Cost Reduction", {
    x: 0.5, y: 0.85, w: 9, h: 0.4,
    fontSize: 15, fontFace: "Arial",
    color: theme.secondary,
    margin: 0
  });

  const leftX = 0.5;
  const leftW = 4.3;

  // Shared experts card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: 1.4, w: leftW, h: 1.65,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: 1.4, w: leftW, h: 0.06,
    fill: { color: theme.accent }
  });
  slide.addText("Shared Experts (N_s)", {
    x: leftX + 0.15, y: 1.55, w: leftW - 0.3, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });
  slide.addText([
    { text: "Always activated — capture common knowledge", options: { bullet: true, breakLine: true } },
    { text: "Ensure minimum expertise coverage across all tokens", options: { bullet: true, breakLine: true } },
    { text: "Reduce redundancy in routed expert selection", options: { bullet: true } }
  ], {
    x: leftX + 0.15, y: 1.95, w: leftW - 0.3, h: 1.0,
    fontSize: 11, fontFace: "Arial",
    color: theme.secondary,
    margin: 0
  });

  // Routed experts card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: 3.2, w: leftW, h: 1.65,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 }
