// slide-08.js — Alignment Results
const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 8, title: 'Alignment Results' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: theme.accent } });

  slide.addText("DeepSeek-V2 Chat (RL) Alignment Results", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 30, fontFace: "Arial", color: theme.primary, bold: true, margin: 0
  });

  slide.addText("SFT on 1.5M conversational sessions + GRPO reinforcement learning", {
    x: 0.5, y: 0.85, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Arial", color: theme.secondary, margin: 0
  });

  const benchmarks = [
    { name: "AlpacaEval 2.0", subtitle: "Length-Controlled Win Rate", score: "38.9%", detail: "Outperforms most open-source models; competitive with closed-source systems" },
    { name: "MT-Bench", subtitle: "Overall Score", score: "8.97", detail: "Strong multi-turn instruction following across diverse task categories" },
    { name: "AlignBench", subtitle: "Overall (Chinese)", score: "7.91", detail: "Outperforms all open-source and most closed-source models in Chinese" }
  ];

  const cardW = 2.85, cardH = 2.4, cardY = 1.4, cardGap = 0.22, startX = 0.5;

  benchmarks.forEach((b, i) => {
    const cx = startX + i * (cardW + cardGap);

    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", color: "000000", blur: 8, offset: 2, angle: 135, opacity: 0.1 }
    });

    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: 0.06,
      fill: { color: i === 2 ? theme.accent : theme.secondary }
    });

    slide.addText(b.name, {
      x: cx + 0.12, y: cardY + 0.15, w: cardW - 0.24, h: 0.35,
      fontSize: 13, fontFace: "Arial", color: theme.primary, bold: true, margin: 0
    });

    slide.addText(b.subtitle, {
      x: cx + 0.12, y: cardY + 0.48, w: cardW - 0.24, h: 0.28,
      fontSize: 10, fontFace: "Arial", color: theme.secondary, margin: 0
    });

    slide.addText(b.score, {
      x: cx, y: cardY + 0.78, w: cardW, h: 0.75,
      fontSize: 42, fontFace: "Arial",
      color: i === 2 ? theme.accent : theme.secondary, bold: true,
      align: "center", valign: "middle", margin: 0
    });

    slide.addText(b.detail, {
      x: cx + 0.12, y: cardY + 1.6, w: cardW - 0.24, h: 0.7,
      fontSize: 9, fontFace: "Arial", color: theme.secondary, margin: 0
    });
  });

  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.1, w: 9, h: 0.8, fill: { color: theme.primary } });

  slide.addShape(pres.shapes.OVAL, { x: 0.7, y: 4.25, w: 0.5, h: 0.5, fill: { color: theme.accent } });
  slide.addText("★", {
    x: 0.7, y: 4.25, w: 0.5, h: 0.5,
    fontSize: 18, fontFace: "Arial", color: "FFFFFF", align: "center", valign: "middle"
  });

  slide.addText("Strongest open-source chat model in Chinese — outperforms all open-source and most closed-source models", {
    x: 1.35, y: 4.1, w: 7.9, h: 0.8,
    fontSize: 13, fontFace: "Arial", color: "FFFFFF", bold: true, valign: "middle", margin: 0
  });

  slide.addText("Post-training: Supervised Fine-Tuning (1.5M sessions) → GRPO-based Reinforcement Learning", {
    x: 0.5, y: 5.05, w: 8.5, h: 0.35,
    fontSize: 10, fontFace: "Arial", color: theme.secondary, margin: 0
  });

  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
