// slide-09.js — Key Takeaways
const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'summary', index: 9, title: 'Key Takeaways' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: theme.accent } });

  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 36, fontFace: "Arial", color: "FFFFFF", bold: true, margin: 0
  });

  slide.addText("Architectural Innovation Unlocks Efficient Scaling", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Arial", color: theme.light, margin: 0
  });

  const takeaways = [
    { num: "01", title: "MLA — Superior KV-Cache Solution", desc: "Achieves better performance than MHA while reducing KV cache by 93.3%. A strictly better alternative to GQA/MQA." },
    { num: "02", title: "DeepSeekMoE — Economical Training", desc: "Fine-grained experts with shared expert isolation enable training a 236B model at 42.5% lower cost than a 67B dense model." },
    { num: "03", title: "Top-Tier Quality at Fraction of Activated Params", desc: "Only 21B activated parameters match or exceed 70B-class dense models (LLaMA 3 70B, Qwen1.5 72B) on MMLU." },
    { num: "04", title: "Strong Multilingual Alignment", desc: "DeepSeek-V2 Chat (RL) is the strongest open-source chat model in Chinese and competitive with closed-source systems in English." },
    { num: "05", title: "Open-Source Availability", desc: "Pareto-optimal positioning: best performance-per-parameter in its class, enabling efficient large-scale deployment." }
  ];

  const itemH = 0.72, startY = 1.6, itemGap = 0.1;

  takeaways.forEach((t, i) => {
    const ty = startY + i * (itemH + itemGap);

    slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: ty, w: 0.55, h: itemH, fill: { color: theme.accent } });
    slide.addText(t.num, {
      x: 0.5, y: ty, w: 0.55, h: itemH,
      fontSize: 16, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });

    slide.addShape(pres.shapes.RECTANGLE, { x: 1.1, y: ty, w: 8.55, h: itemH, fill: { color: theme.secondary, transparency: 40 } });

    slide.addText(t.title, {
      x: 1.25, y: ty + 0.08, w: 8.3, h: 0.3,
      fontSize: 13, fontFace: "Arial", color: "FFFFFF", bold: true, margin: 0
    });

    slide.addText(t.desc, {
      x: 1.25, y: ty + 0.36, w: 8.3, h: 0.32,
      fontSize: 10, fontFace: "Arial", color: theme.light, margin: 0
    });
  });

  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("9", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "caf0f8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-09-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

